const BYREF = Object.fromEntries(GITA.map((v) => [v.ref, v]));

const KEYWORD_THEMES = [
  [["grief","grieve","loss","lost someone","died","death","passed away","mourn","funeral"],["Grief & Loss","The Eternal Self"]],
  [["anxious","anxiety","worried","worry","afraid","fear","scared","nervous","dread","panic"],["Courage","Equanimity","The Restless Mind"]],
  [["angry","anger","rage","furious","resent","frustrat","irritat"],["Desire & Anger","Self-Mastery"]],
  [["decision","decide","choose","choice","stuck","confused","torn","crossroad","uncertain","what should i do"],["Action & Duty","Letting Go of Outcomes"]],
  [["overwhelm","stress","burnout","burned out","exhausted","too much","pressure","work"],["Equanimity","Self-Mastery","Peace"]],
  [["lonely","alone","isolated","abandoned","disconnected"],["Devotion & Trust","Compassion"]],
  [["ego","pride","arrogan","humiliat","embarrass","failure","failed","rejected"],["Self-Mastery","Letting Go of Outcomes"]],
  [["meaning","purpose","pointless","empty","directionless","why bother"],["Action & Duty","The Eternal Self","Peace"]],
  [["calm","peace","rest","settle","still"],["Peace","Equanimity"]],
  [["craving","desire","want","tempt","addict","obsess"],["Desire & Anger","Self-Mastery"]],
  [["restless","distracted","can't focus","racing thoughts","overthink"],["The Restless Mind","Self-Mastery"]],
];
const STOP = new Set(["about","there","their","would","could","should","really","because","myself","being","feel","feeling","right","going","things","something","someone","through","where","which","while","these","those","always","never"]);
function matchVerses(text, max = 5) {
  const t = (text || "").toLowerCase();
  const themeScore = new Map();
  const terms = new Set();
  for (const [keys, themes] of KEYWORD_THEMES)
    if (keys.some((k) => t.includes(k))) { themes.forEach((th) => themeScore.set(th, (themeScore.get(th) || 0) + 1)); keys.forEach((k) => { if (t.includes(k)) k.split(" ").forEach((w) => w.length > 3 && terms.add(w)); }); }
  t.split(/[^a-z]+/).forEach((w) => { if (w.length > 4 && !STOP.has(w)) terms.add(w); });
  const arr = Array.from(terms);
  if (!arr.length) return [];
  const scored = GITA.map((v) => {
    const en = (v.en || "").toLowerCase();
    let s = 0; for (const term of arr) if (en.includes(term)) s += 1;
    const meta = FEAT[v.ref];
    const vThemes = meta ? meta.themes : (VTHEM[v.ref] || []).map(i => TH_NAMES[i]);
    if (vThemes.length) s += vThemes.reduce((a, th) => a + (themeScore.get(th) || 0), 0) * 2;
    return { v, s };
  }).filter((x) => x.s > 0).sort((a, b) => b.s - a.s);
  return scored.slice(0, max).map((x) => x.v);
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Inter:wght@400;500;600&family=Noto+Serif+Devanagari:wght@400;500&family=Noto+Serif+Gujarati:wght@400;500&display=swap');
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
:root{--night:#0c1230;--night2:#0f1638;--surface:#161e48;--surface2:#1d2758;--line:rgba(176,188,255,.12);--line2:rgba(176,188,255,.20);--krishna:#7d90ec;--krishna2:#5566cf;--gold:#e7b466;--gold2:#f2cd8c;--text:#eef0fb;--verse:#f6efdf;--muted:#9aa3cb;--muted2:#6d76a3;--display:'Cormorant Garamond',Georgia,serif;--deva:'Noto Serif Devanagari',serif;--ui:'Inter',system-ui,-apple-system,sans-serif}
.app{min-height:100vh;background:radial-gradient(120% 60% at 50% -10%,rgba(231,180,102,.10),transparent 55%),radial-gradient(90% 50% at 50% 0%,rgba(125,144,236,.10),transparent 50%),linear-gradient(180deg,var(--night),var(--night2));color:var(--text);font-family:var(--ui);padding-bottom:84px}
.wrap{max-width:680px;margin:0 auto;padding:0 18px}
.head{padding:24px 0 12px;text-align:center}
.mark{display:inline-flex;align-items:center;gap:9px;color:var(--gold2)}
.brand{font-family:var(--display);font-size:33px;font-weight:600;letter-spacing:.02em;line-height:1;margin-top:6px}
.tag{color:var(--muted);font-size:12px;margin-top:5px;letter-spacing:.05em;text-transform:uppercase}
.card{background:linear-gradient(180deg,var(--surface),var(--surface2) 120%);border:1px solid var(--line);border-radius:20px;padding:22px 20px;position:relative;overflow:hidden}
.eyebrow{font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted2);font-weight:600}
.dawn{position:absolute;inset:-40% -10% auto -10%;height:75%;background:radial-gradient(60% 100% at 50% 0%,rgba(231,180,102,.22),rgba(125,144,236,.06) 45%,transparent 70%);filter:blur(6px);pointer-events:none}
.ref{display:inline-block;font-family:var(--display);font-style:italic;font-size:17px;color:var(--gold2);position:relative}
.dev{font-family:var(--deva);font-size:18px;line-height:2.05;color:var(--verse);white-space:pre-line;margin:13px 0 6px;position:relative}
.translit{font-family:var(--display);font-style:italic;color:var(--muted);font-size:14px;line-height:1.5;white-space:pre-line;position:relative;margin-bottom:4px}
.en{font-family:var(--display);font-size:22px;line-height:1.45;color:var(--verse);margin:14px 0 2px;position:relative;font-weight:500}
.note{position:relative;color:var(--krishna);font-size:14px;margin-top:12px;padding-left:13px;border-left:2px solid var(--krishna2)}
.tagrow{display:flex;flex-wrap:wrap;gap:6px;margin-top:11px;position:relative}
.ttag{font-size:11px;color:var(--krishna);background:rgba(125,144,236,.10);border:1px solid var(--line);border-radius:999px;padding:3px 9px}
.guj-wrap{position:relative;margin-top:12px}
.guj{font-family:'Noto Serif Gujarati','Noto Serif Devanagari',serif;font-size:16px;line-height:1.75;color:var(--verse)}
.ai-tag{font-family:var(--ui);font-size:9.5px;letter-spacing:.08em;color:var(--muted2);border:1px solid var(--line);border-radius:6px;padding:2px 6px;margin-left:8px;vertical-align:middle;white-space:nowrap;text-transform:uppercase}
.cmp{margin-top:10px;position:relative}
.cmp-btn{background:none;border:none;color:var(--krishna);font-family:var(--ui);font-size:12.5px;cursor:pointer;padding:2px 0;text-decoration:underline;text-underline-offset:3px}
.cmp-body{margin-top:8px;border-left:2px solid var(--line2);padding-left:12px}
.cmp-row{font-size:14px;line-height:1.5;color:var(--muted);margin-top:9px}
.cmp-row:first-child{margin-top:0}
.cmp-lbl{display:block;font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted2);margin-bottom:2px}
.poolseg{margin:0 0 12px}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.btn{font-family:var(--ui);font-size:14px;font-weight:500;color:var(--text);background:rgba(125,144,236,.14);border:1px solid var(--line2);border-radius:12px;padding:11px 15px;cursor:pointer;transition:.18s;display:inline-flex;align-items:center;gap:7px}
.btn:hover{background:rgba(125,144,236,.24)}.btn:active{transform:translateY(1px)}
.btn.gold{background:linear-gradient(180deg,var(--gold),#d99f4e);color:#2a1c05;border-color:transparent;font-weight:600}
.btn.gold:hover{filter:brightness(1.06)}.btn.ghost{background:transparent}.btn.icon{padding:11px 12px}.btn:disabled{opacity:.5;cursor:default}
.lbl{font-size:12.5px;color:var(--muted);margin-bottom:8px;display:flex;justify-content:space-between;align-items:center}
textarea{width:100%;background:rgba(8,12,32,.5);border:1px solid var(--line);border-radius:14px;color:var(--text);font-family:var(--ui);font-size:15px;line-height:1.5;padding:13px 14px;resize:vertical;min-height:84px;outline:none}
textarea:focus{border-color:var(--krishna2)}.saved-pill{font-size:11.5px;color:var(--gold2)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 6px}
.chip{font-size:13px;color:var(--muted);background:rgba(125,144,236,.10);border:1px solid var(--line);border-radius:999px;padding:8px 13px;cursor:pointer;transition:.16s}
.chip:hover{color:var(--text);border-color:var(--line2)}
.chip.on{background:rgba(231,180,102,.16);color:var(--gold2);border-color:rgba(231,180,102,.35)}
.cnum{font-size:13px;color:var(--muted);background:rgba(125,144,236,.10);border:1px solid var(--line);border-radius:10px;min-width:38px;text-align:center;padding:8px 6px;cursor:pointer;transition:.16s}
.cnum:hover{color:var(--text)}.cnum.on{background:rgba(231,180,102,.16);color:var(--gold2);border-color:rgba(231,180,102,.35)}
.cgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(40px,1fr));gap:7px;margin:12px 0 4px}
.guide-out{margin-top:16px;font-size:15.5px;line-height:1.62;color:var(--text);white-space:pre-wrap}
.guide-out .vref{color:var(--gold2);font-weight:600;font-family:var(--display);font-style:italic}
.thinking{display:flex;align-items:center;gap:11px;color:var(--muted);font-size:14px;margin-top:14px}
.spin{width:16px;height:16px;border:2px solid var(--line2);border-top-color:var(--gold);border-radius:50%;animation:sp .8s linear infinite}
@keyframes sp{to{transform:rotate(360deg)}}
.disc{margin-top:14px;font-size:12px;color:var(--muted2);line-height:1.55}
.mini{border:1px solid var(--line);border-radius:15px;padding:15px 16px;background:rgba(8,12,32,.32);margin-top:11px}
.mini .ref{font-size:15px}.mini .en2{font-family:var(--display);font-size:18px;line-height:1.42;color:var(--verse);margin:10px 0 0;font-weight:500}.mini .note{font-size:13px;margin-top:10px}
.mini-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.star{cursor:pointer;color:var(--muted2);flex:none;padding:2px;transition:.16s}.star.on{color:var(--gold)}.star:hover{color:var(--gold2)}
.search{width:100%;background:rgba(8,12,32,.5);border:1px solid var(--line);border-radius:14px;color:var(--text);font-family:var(--ui);font-size:15px;padding:13px 15px;outline:none;margin-bottom:6px}
.search:focus{border-color:var(--krishna2)}
.count{font-size:12.5px;color:var(--muted2);margin:14px 2px 2px}
.empty{text-align:center;color:var(--muted);padding:30px 16px;font-size:14.5px;line-height:1.6}
.empty .big{font-family:var(--display);font-size:21px;color:var(--text);font-style:italic;margin-bottom:8px}
.sect-h{font-family:var(--display);font-size:26px;font-weight:600;margin:4px 0 2px}
.sect-s{color:var(--muted);font-size:13.5px;margin-bottom:16px;line-height:1.5}
.seg{display:inline-flex;background:rgba(8,12,32,.4);border:1px solid var(--line);border-radius:12px;padding:3px;gap:3px;margin-bottom:12px}
.seg button{border:none;background:none;color:var(--muted);font-family:var(--ui);font-size:13.5px;padding:8px 15px;border-radius:9px;cursor:pointer}
.seg button.on{background:rgba(231,180,102,.16);color:var(--gold2)}
.chtitle{font-family:var(--display);font-size:20px;color:var(--text);margin:8px 0 2px}
.nav{position:fixed;bottom:0;left:0;right:0;background:rgba(10,15,40,.86);backdrop-filter:blur(14px);border-top:1px solid var(--line);display:flex;z-index:20}
.nav-in{max-width:680px;margin:0 auto;display:flex;width:100%}
.tab{flex:1;background:none;border:none;color:var(--muted2);font-family:var(--ui);font-size:11px;padding:11px 0 max(11px,env(safe-area-inset-bottom));cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:4px;transition:.16s}
.tab.on{color:var(--gold2)}
.stack>*+*{margin-top:14px}
.fade{animation:fade .5s ease both}
@keyframes fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.fade,.dawn{animation:none}.spin{animation-duration:1.4s}}
`;

function Wheel({ s = 18 }) {
  return (<svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4">
    <circle cx="12" cy="12" r="9" /><circle cx="12" cy="12" r="2.4" />
    {[0,45,90,135].map((a)=>(<line key={a} x1={12-7*Math.cos(a*Math.PI/180)} y1={12-7*Math.sin(a*Math.PI/180)} x2={12+7*Math.cos(a*Math.PI/180)} y2={12+7*Math.sin(a*Math.PI/180)} />))}
  </svg>);
}
const Star = ({ on }) => (<svg className={"star"+(on?" on":"")} width="20" height="20" viewBox="0 0 24 24" fill={on?"currentColor":"none"} stroke="currentColor" strokeWidth="1.5"><path d="M12 3.2l2.5 5.6 6.1.6-4.6 4 1.4 6-5.4-3.2L6.6 19.4l1.4-6-4.6-4 6.1-.6z" /></svg>);
function CompassIcon(){return(<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="12" cy="12" r="9"/><path d="M15.5 8.5l-2 5-5 2 2-5z" fill="currentColor" stroke="none" opacity=".85"/></svg>);}
function GridIcon(){return(<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="4" y="4" width="7" height="7" rx="1.5"/><rect x="13" y="4" width="7" height="7" rx="1.5"/><rect x="4" y="13" width="7" height="7" rx="1.5"/><rect x="13" y="13" width="7" height="7" rx="1.5"/></svg>);}
function ShuffleIcon(){return(<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6"><path d="M3 7h4l3 5 3 5h5M3 17h4l3-5M14 7h5M17 4l3 3-3 3M17 14l3 3-3 3"/></svg>);}

function GujaratiLine({ v }) {
  const baked = (FEAT[v.ref] && FEAT[v.ref].gu) || v.gu || null;
  if (baked) return <div className="guj-wrap"><div className="guj">{baked}<span className="ai-tag">અનુવાદ</span></div></div>;
  return null;
}

function Readings({ v }) {
  const [open, setOpen] = useState(false);
  if (!v.es && !v.er) return null;
  return (
    <div className="cmp">
      <button className="cmp-btn" onClick={() => setOpen(!open)}>{open ? "Hide other readings" : "Compare readings"}</button>
      {open && <div className="cmp-body">
        {v.es && <div className="cmp-row"><span className="cmp-lbl">Śaṅkara · Advaita</span>{v.es}</div>}
        {v.er && <div className="cmp-row"><span className="cmp-lbl">Rāmānuja · Viśiṣṭādvaita</span>{v.er}</div>}
      </div>}
    </div>
  );
}

const wmCache = new Map();
function fetchChapterWM(ch) {
  if (!wmCache.has(ch)) {
    wmCache.set(ch, fetch(`${import.meta.env.BASE_URL}wm/ch${ch}.json`).then((r) => {
      if (!r.ok) throw new Error("wm fetch failed");
      return r.json();
    }));
  }
  return wmCache.get(ch);
}
function WordByWord({ v }) {
  const [open, setOpen] = useState(false);
  const [state, setState] = useState({ status: "idle" });
  const toggle = () => {
    const next = !open;
    setOpen(next);
    if (next && state.status === "idle") {
      setState({ status: "loading" });
      fetchChapterWM(v.ch)
        .then((data) => setState({ status: "ready", wm: data[v.ref] || "" }))
        .catch(() => setState({ status: "error" }));
    }
  };
  const rows = useMemo(() => {
    if (state.status !== "ready" || !state.wm) return [];
    return state.wm.split("; ").map((entry) => {
      const i = entry.indexOf("—");
      return i === -1 ? { full: entry } : { word: entry.slice(0, i).trim(), meaning: entry.slice(i + 1).trim() };
    });
  }, [state]);
  return (
    <div className="cmp">
      <button className="cmp-btn" onClick={toggle}>{open ? "Hide word meanings" : "Word by word"}</button>
      {open && <div className="cmp-body">
        {state.status === "loading" && <div className="cmp-row">Loading…</div>}
        {state.status === "error" && <div className="disc">Couldn't load word meanings (offline?).</div>}
        {state.status === "ready" && rows.map((r, i) => (
          <div className="cmp-row" key={i}>
            {r.full ? r.full : <><span style={{ fontFamily: "var(--display)", fontStyle: "italic" }}>{r.word}</span> — {r.meaning}</>}
          </div>
        ))}
      </div>}
    </div>
  );
}

function VerseCard({ v, fav, onFav, onMark, marked }) {
  const meta = FEAT[v.ref];
  return (
    <div className="mini fade" id={onMark ? "v-" + v.ref : undefined}>
      <div className="mini-head"><span className="ref">Gītā {v.ref}</span>
        <span onClick={() => onFav(v.ref)} role="button" aria-label="Save verse"><Star on={fav} /></span></div>
      {v.sa && <div className="dev" style={{ fontSize: 16, lineHeight: 1.95 }}>{v.sa}</div>}
      {v.tr && <div className="translit">{v.tr}</div>}
      <div className="en2">{v.en}</div>
      <Readings v={v} />
      <WordByWord v={v} />
      {meta && <div className="note">{meta.note}</div>}
      {meta && <div className="tagrow">{meta.themes.map((t) => <span className="ttag" key={t}>{t}</span>)}</div>}
      <GujaratiLine v={v} />
      {onMark && <div className="cmp"><button className="cmp-btn" onClick={() => onMark(v)}>{marked ? "✓ Marked — your place" : "Mark my place"}</button></div>}
    </div>
  );
}

const Credits = () => (
  <div className="disc" style={{ textAlign: "center", marginTop: 22 }}>
    701 verses, complete. Sanskrit, transliteration &amp; word-by-word meanings from the public-domain <i>gita/gita</i> dataset. English: Swami Sivananda (primary), with Śaṅkara/Advaita (Gambhirananda) and Rāmānuja/Viśiṣṭādvaita (Adidevananda) readings for comparison. Gujarati for 45 curated verses is translated &amp; reviewed; reflections and design original.
  </div>
);

export default function App() {
  const [tab, setTab] = useState("today");
  const [ready, setReady] = useState(false);
  const [favorites, setFavorites] = useState([]);
  const [journal, setJournal] = useState({});
  const todayKey = (d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`)(new Date());
  const dayOfYear = useMemo(() => {
    const n = new Date(), start = new Date(n.getFullYear(), 0, 0);
    return Math.floor((n - start) / 86400000);
  }, []);
  const [pool, setPool] = useState("all");
  const [shuffleRef, setShuffleRef] = useState(null);
  const activeList = pool === "curated" ? FEATURED_LIST : GITA;
  const choosePool = (p) => { setPool(p); setShuffleRef(null); };
  const dayVerse = shuffleRef ? BYREF[shuffleRef] : activeList[dayOfYear % activeList.length];
  const [bookmark, setBookmark] = useState(null);
  const [jumpRef, setJumpRef] = useState(null);

  useEffect(() => { (async () => {
    try { const f = localStorage.getItem("sarathi:favorites"); if (f) setFavorites(JSON.parse(f)); } catch (e) {}
    try { const j = localStorage.getItem("sarathi:journal"); if (j) setJournal(JSON.parse(j)); } catch (e) {}
    try { const b = localStorage.getItem("sarathi:bookmark"); if (b) setBookmark(JSON.parse(b)); } catch {}
    setReady(true);
  })(); }, []);

  const setMark = (v) => {
    const next = { ref: v.ref, ch: v.ch };
    setBookmark(next);
    try { localStorage.setItem("sarathi:bookmark", JSON.stringify(next)); } catch {}
  };
  const goToBookmark = () => {
    if (!bookmark) return;
    setTab("explore");
    setJumpRef(bookmark.ref);
  };

  const toggleFav = async (ref) => {
    const next = favorites.includes(ref) ? favorites.filter((x) => x !== ref) : [...favorites, ref];
    setFavorites(next);
    try { localStorage.setItem("sarathi:favorites", JSON.stringify(next)); } catch (e) {}
  };
  const saveJournal = async (text) => {
    const next = { ...journal };
    if (text.trim()) next[todayKey] = { verseRef: dayVerse.ref, text }; else delete next[todayKey];
    setJournal(next);
    try { localStorage.setItem("sarathi:journal", JSON.stringify(next)); } catch (e) {}
  };

  const exportBackup = () => {
    const data = {
      app: "sarathi", version: 1, exportedAt: new Date().toISOString(),
      favorites, journal,
      bookmark: JSON.parse(localStorage.getItem("sarathi:bookmark") || "null"),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `sarathi-backup-${todayKey}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };
  const importBackup = async (file) => {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.app !== "sarathi" || !Array.isArray(data.favorites) || typeof data.journal !== "object") {
      throw new Error("invalid backup");
    }
    const newFavs = data.favorites.filter((r) => !favorites.includes(r));
    const nextFavorites = [...favorites, ...newFavs];
    const newEntries = Object.keys(data.journal).filter((d) => !(d in journal));
    const nextJournal = { ...data.journal, ...journal };
    setFavorites(nextFavorites);
    setJournal(nextJournal);
    try { localStorage.setItem("sarathi:favorites", JSON.stringify(nextFavorites)); } catch {}
    try { localStorage.setItem("sarathi:journal", JSON.stringify(nextJournal)); } catch {}
    if (data.bookmark && !localStorage.getItem("sarathi:bookmark")) {
      try { localStorage.setItem("sarathi:bookmark", JSON.stringify(data.bookmark)); } catch {}
    }
    return { verses: newFavs.length, reflections: newEntries.length };
  };

  return (
    <div className="app"><style>{CSS}</style><div className="wrap">
      <div className="head">
        <div className="mark"><Wheel s={19} /><span style={{ fontSize: 12, letterSpacing: ".14em" }}>SĀRATHI</span></div>
        <div className="brand">The Steady Mind</div>
        <div className="tag">a daily compass · Bhagavad Gītā</div>
      </div>

      {tab === "today" && <Today v={dayVerse} fav={favorites.includes(dayVerse.ref)} onFav={toggleFav}
        onShuffle={() => setShuffleRef(activeList[Math.floor(Math.random() * activeList.length)].ref)}
        isToday={!shuffleRef} pool={pool} setPool={choosePool}
        entry={journal[todayKey]?.text || ""} onSave={saveJournal} ready={ready}
        bookmark={bookmark} goToBookmark={goToBookmark} />}
      {tab === "guidance" && <Guidance favorites={favorites} onFav={toggleFav} />}
      {tab === "explore" && <Explore favorites={favorites} onFav={toggleFav} onMark={setMark} bookmarkRef={bookmark?.ref} jumpRef={jumpRef} onJumped={() => setJumpRef(null)} />}
      {tab === "saved" && <Saved favorites={favorites} journal={journal} onFav={toggleFav} onExport={exportBackup} onImport={importBackup} />}
    </div>

      <nav className="nav"><div className="nav-in">
        {[["today","Today",<Wheel s={20}/>],["guidance","Guidance",<CompassIcon/>],["explore","Explore",<GridIcon/>],["saved","Saved",<Star on={false}/>]].map(([k,label,icon])=>(
          <button key={k} className={"tab"+(tab===k?" on":"")} onClick={()=>setTab(k)}>{icon}<span>{label}</span></button>
        ))}
      </div></nav>
    </div>
  );
}

function Today({ v, fav, onFav, onShuffle, isToday, pool, setPool, entry, onSave, ready, bookmark, goToBookmark }) {
  const [text, setText] = useState(entry);
  const [flag, setFlag] = useState(false);
  useEffect(() => { setText(entry); }, [entry, v.ref]);
  const commit = () => { onSave(text); setFlag(true); setTimeout(() => setFlag(false), 1600); };
  const meta = FEAT[v.ref];
  return (
    <div className="stack">
      <div className="seg poolseg">
        <button className={pool === "all" ? "on" : ""} onClick={() => setPool("all")}>All 701</button>
        <button className={pool === "curated" ? "on" : ""} onClick={() => setPool("curated")}>Curated</button>
      </div>
      <div className="card fade"><div className="dawn" />
        <div className="eyebrow" style={{ position: "relative" }}>{isToday ? (pool === "curated" ? "Today · curated" : "Today's verse") : "Drawn at random"}</div>
        <div style={{ height: 8 }} /><div className="ref">Gītā {v.ref}</div>
        {v.sa && <div className="dev">{v.sa}</div>}
        {v.tr && <div className="translit">{v.tr}</div>}
        <div className="en">{v.en}</div>
        <Readings v={v} />
        <WordByWord v={v} />
        {meta && <div className="note">{meta.note}</div>}
        {meta && <div className="tagrow">{meta.themes.map((t) => <span className="ttag" key={t}>{t}</span>)}</div>}
        <GujaratiLine v={v} />
        <div className="row" style={{ marginTop: 18, position: "relative" }}>
          <button className="btn ghost icon" onClick={() => onFav(v.ref)} aria-label="Save"><Star on={fav} /></button>
          <button className="btn" onClick={onShuffle}><ShuffleIcon /> Draw another verse</button>
        </div>
      </div>
      <div className="card fade">
        <div className="lbl"><span>A reflection for today {flag && <span className="saved-pill">· saved</span>}</span></div>
        <textarea value={text} placeholder="What does this verse stir in you today? Where does it meet your life right now?"
          onChange={(e) => setText(e.target.value)} onBlur={commit} />
        <div className="row" style={{ marginTop: 12 }}><button className="btn gold" onClick={commit} disabled={!ready}>Save reflection</button></div>
      </div>
      {bookmark && <div className="card fade">
        <div className="eyebrow">Continue reading</div>
        <div style={{ marginTop: 8 }}><span className="ref">Gītā {bookmark.ref}</span> · {CHAPTERS[bookmark.ch - 1]}</div>
        <div className="row" style={{ marginTop: 12 }}><button className="btn" onClick={goToBookmark}>Continue →</button></div>
      </div>}
    </div>
  );
}

function Guidance({ favorites, onFav }) {
  const [input, setInput] = useState("");
  const [out, setOut] = useState(""); const [loading, setLoading] = useState(false);
  const [related, setRelated] = useState([]);
  const chips = [
    ["A hard decision","I'm facing a hard decision and feel torn about which way to go."],
    ["Grief or loss","I'm grieving a loss and finding it hard to carry."],
    ["Anxiety","I feel anxious and my mind won't settle."],
    ["Anger","I'm holding a lot of anger and resentment right now."],
    ["Feeling stuck","I feel stuck and unsure of my purpose or direction."],
    ["Overwhelm at work","I'm overwhelmed and burning out from work."],
    ["Self-doubt","I keep doubting myself after a failure."],
  ];
  const ask = (situation) => {
    const text = situation ?? input; if (!text.trim()) return;
    setLoading(true); setOut("");
    const MSGS = {"Action & Duty":"The Gītā meets you in the space between knowing what is right and finding the strength to act. Your duty, however it appears, is already the path.","Letting Go of Outcomes":"The Gītā invites you to pour yourself fully into what you're doing — and then release your grip on what comes next. That release is itself a kind of freedom.","Equanimity":"The Gītā points to a steadiness that doesn't come from life going smoothly, but from something inside you that isn't moved by each wave. That ground is already here.","The Eternal Self":"Beneath whatever is shifting or hurting right now, the Gītā points to something in you that is unchanged — witnessing, quiet, whole.","Grief & Loss":"The Gītā does not ask you to stop feeling. It asks you to grieve fully — and then to recognize that what you most loved was never only in what was lost.","Courage":"The Gītā meets this moment of hesitation with one quiet call: rise. Not because the path is clear, but because you are capable of walking it.","Desire & Anger":"The Gītā traces a familiar arc — from wanting, through frustration, into something darker. Seeing the chain is already the first step to loosening it.","The Restless Mind":"The Gītā is patient with the restless mind. The answer it offers: practice, and again practice — each return is the practice itself, not a failure of it.","Devotion & Trust":"The Gītā asks whether you might lay down the weight you've been carrying alone — not into nothing, but into something that holds you in return.","Self-Mastery":"The Gītā places the key in your own hands. The one who can lift you higher is already present — in the choices you make, the habits you tend each day.","Peace":"The Gītā points toward a peace that doesn't depend on everything going right. It waits in the quiet beneath the noise, available now.","Compassion":"The Gītā sees you in all things and all things in you. From that recognition, something like compassion arises as the most natural response."};
    setTimeout(() => {
      const matches = matchVerses(text, 7);
      setRelated(matches);
      const topThemes = [...new Set(matches.flatMap(v => {
        const f = FEAT[v.ref]; if (f) return f.themes;
        const vi = VTHEM[v.ref]; return vi ? vi.map(i => TH_NAMES[i]) : [];
      }))].slice(0, 2);
      const intro = topThemes.length ? (MSGS[topThemes[0]] || "The Gītā holds a teaching for what you're facing.") : "The Gītā holds a teaching for what you're facing.";
      const note = topThemes.length > 1 ? ` The verses below draw especially from the teachings on ${topThemes.join(" and ")}.` : topThemes.length ? ` The verses below draw from the teachings on ${topThemes[0]}.` : "";
      setOut(intro + note + " Sit with the ones that meet you where you are.");
      setLoading(false);
    }, 120);
  };
  const rendered = useMemo(() => {
    if (!out) return null;
    return out.split(/(\b\d{1,2}\.\d{1,2}(?:[-]\d{1,2})?\b)/g).map((p, i) =>
      /^\d{1,2}\.\d/.test(p) ? <span key={i} className="vref">{p}</span> : p);
  }, [out]);
  return (
    <div className="stack">
      <div><div className="sect-h">What are you facing?</div>
        <div className="sect-s">Describe your situation in your own words. Sārathi reflects on it through the Gītā and surfaces the verses that speak to it — offline, always available.</div></div>
      <div className="card fade">
        <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="e.g. I have to choose between two paths and I'm afraid of getting it wrong…" />
        <div className="chips">{chips.map(([l, full]) => <button key={l} className="chip" onClick={() => { setInput(full); ask(full); }}>{l}</button>)}</div>
        <div className="row" style={{ marginTop: 10 }}><button className="btn gold" onClick={() => ask()} disabled={loading || !input.trim()}><CompassIcon /> Seek guidance</button></div>
        {loading && <div className="thinking"><div className="spin" /> Sitting with your words…</div>}
        {rendered && !loading && <div className="guide-out fade">{rendered}</div>}
        {!loading && out && <div className="disc">A reflection drawn from the Gītā — not a substitute for the people who care about you, or for professional support when you need it.</div>}
      </div>
      {related.length > 0 && !loading && <div><div className="count">Verses that speak to this</div>
        {related.map((v) => <VerseCard key={v.ref} v={v} fav={favorites.includes(v.ref)} onFav={onFav} />)}</div>}
    </div>
  );
}

function Explore({ favorites, onFav, onMark, bookmarkRef, jumpRef, onJumped }) {
  const [mode, setMode] = useState("themes");
  const [scope, setScope] = useState("curated");
  const [theme, setTheme] = useState(null);
  const [chapter, setChapter] = useState(1);
  const [q, setQ] = useState("");
  const themeList = theme ? FEATURED_LIST.filter((v) => FEAT[v.ref].themes.includes(theme)) : FEATURED_LIST;
  const allThemeList = theme ? GITA.filter((v) => (VTHEM[v.ref] || []).includes(TH_NAMES.indexOf(theme))) : GITA;
  const qRaw = q.trim();
  const s = qRaw.toLowerCase();
  const searchList = s ? GITA.filter((v) => v.en.toLowerCase().includes(s) || v.ref === s || v.tr.toLowerCase().includes(s) || (v.gu && v.gu.includes(qRaw))) : null;
  const chapList = GITA.filter((v) => v.ch === chapter);
  useEffect(() => {
    if (!jumpRef) return;
    setMode("all"); setQ(""); setChapter(BYREF[jumpRef].ch);
    let tries = 0;
    const ref = jumpRef;
    const scroll = () => {
      const el = document.getElementById("v-" + ref);
      if (el) window.scrollTo(0, el.getBoundingClientRect().top + window.scrollY - 8);
    };
    const t = setInterval(() => {
      if (document.getElementById("v-" + ref) || ++tries > 25) {
        clearInterval(t);
        scroll();
        // fonts swapping in shift layout above the verse; re-anchor once they settle
        document.fonts.ready.then(scroll);
        onJumped();
      }
    }, 120);
    return () => clearInterval(t);
  }, [jumpRef, onJumped]);
  return (
    <div className="stack">
      <div><div className="sect-h">Explore the Gītā</div>
        <div className="sect-s">All 701 verses, with verified Sanskrit and translation. Browse the curated themes, or read straight through any chapter.</div></div>
      <div className="seg">
        <button className={mode === "themes" ? "on" : ""} onClick={() => setMode("themes")}>Themes</button>
        <button className={mode === "all" ? "on" : ""} onClick={() => setMode("all")}>All verses</button>
      </div>

      {mode === "themes" && (<>
        <div className="chips">
          <button className={"chip" + (!theme ? " on" : "")} onClick={() => setTheme(null)}>All themes</button>
          {TH_NAMES.map((t) => <button key={t} className={"chip" + (theme === t ? " on" : "")} onClick={() => setTheme(theme === t ? null : t)}>{t}</button>)}
        </div>
        <div className="seg">
          <button className={scope === "curated" ? "on" : ""} onClick={() => setScope("curated")}>Curated</button>
          <button className={scope === "all" ? "on" : ""} onClick={() => setScope("all")}>All 701</button>
        </div>
        {scope === "curated" ? (
          <>
            <div className="count">{themeList.length} curated verse{themeList.length === 1 ? "" : "s"}{theme ? " · " + theme : ""}</div>
            {themeList.map((v) => <VerseCard key={v.ref} v={v} fav={favorites.includes(v.ref)} onFav={onFav} />)}
          </>
        ) : (
          <>
            <div className="count">{allThemeList.length} verse{allThemeList.length === 1 ? "" : "s"}{theme ? " · " + theme : ""}</div>
            {allThemeList.slice(0, 60).map((v) => <VerseCard key={v.ref} v={v} fav={favorites.includes(v.ref)} onFav={onFav} />)}
            {allThemeList.length > 60 && <div className="count">Showing first 60. Pick a theme to narrow.</div>}
          </>
        )}
      </>)}

      {mode === "all" && (<>
        <input className="search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search all verses — English, ગુજરાતી, or a reference like 9.22" />
        {s ? (
          <>
            <div className="count">{searchList.length} match{searchList.length === 1 ? "" : "es"}</div>
            {searchList.length === 0 ? <div className="empty"><div className="big">Nothing found</div>Try another word, or a reference like 2.47.</div>
              : searchList.slice(0, 60).map((v) => <VerseCard key={v.ref} v={v} fav={favorites.includes(v.ref)} onFav={onFav} />)}
            {searchList.length > 60 && <div className="count">Showing first 60. Narrow your search to see more.</div>}
          </>
        ) : (
          <>
            <div className="cgrid">{Array.from({ length: 18 }, (_, i) => i + 1).map((c) => (
              <button key={c} className={"cnum" + (chapter === c ? " on" : "")} onClick={() => setChapter(c)}>{c}</button>))}</div>
            <div className="chtitle">{chapter}. {CHAPTERS[chapter - 1]}</div>
            <div className="sect-s">{CHAP_INTRO[chapter - 1]}</div>
            <div className="count">{chapList.length} verses</div>
            {chapList.map((v) => <VerseCard key={v.ref} v={v} fav={favorites.includes(v.ref)} onFav={onFav} onMark={onMark} marked={bookmarkRef === v.ref} />)}
          </>
        )}
      </>)}
      <Credits />
    </div>
  );
}

function Saved({ favorites, journal, onFav, onExport, onImport }) {
  const favVerses = favorites.map((r) => BYREF[r]).filter(Boolean);
  const entries = Object.entries(journal).sort((a, b) => b[0].localeCompare(a[0]));
  const fileRef = useRef(null);
  const [status, setStatus] = useState("");
  const pickFile = () => fileRef.current && fileRef.current.click();
  const handleFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    try {
      const { verses, reflections } = await onImport(file);
      setStatus(`Restored: ${verses} verses, ${reflections} reflections.`);
    } catch {
      setStatus("That file doesn't look like a Sārathi backup.");
    }
  };
  return (
    <div className="stack">
      <div><div className="sect-h">Saved</div><div className="sect-s">Verses you've kept, and the reflections you've written.</div></div>
      <div className="count">Favorite verses</div>
      {favVerses.length === 0 ? <div className="empty"><div className="big">No saved verses yet</div>Tap the star on any verse to keep it here.</div>
        : favVerses.map((v) => <VerseCard key={v.ref} v={v} fav onFav={onFav} />)}
      <div className="count" style={{ marginTop: 22 }}>Your reflections</div>
      {entries.length === 0 ? <div className="empty"><div className="big">No reflections yet</div>Write one beneath today's verse — it'll wait for you here.</div>
        : entries.map(([date, e]) => { const v = BYREF[e.verseRef]; return (
          <div className="mini fade" key={date}>
            <div className="mini-head">
              <span className="ref">{new Date(date + "T00:00").toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" })}</span>
              {v && <span className="saved-pill">Gītā {v.ref}</span>}</div>
            <div style={{ marginTop: 10, fontSize: 15, lineHeight: 1.6, whiteSpace: "pre-wrap" }}>{e.text}</div>
          </div>); })}
      <div className="count" style={{ marginTop: 22 }}>Backup</div>
      <div className="disc">Your reflections live only in this browser. A backup file protects them if you clear your data or switch devices.</div>
      <div className="row" style={{ marginTop: 10 }}>
        <button className="btn" onClick={onExport}>Export backup</button>
        <button className="btn" onClick={pickFile}>Import backup</button>
        <input ref={fileRef} type="file" accept="application/json" style={{ display: "none" }} onChange={handleFile} />
      </div>
      {status && <div className="disc" style={{ marginTop: 8 }}>{status}</div>}
    </div>
  );
}
